// FUNCTION: BFME2 0x004A7E67 size=273 name=?rva004A7E67@SupplyWarehouseDockUpdate@@UAE_NPAVObject@@H@Z evidence=?:placeholder tier=A
// Hands one box to the docking supply truck. Not close enough (twice the truck's radius, squared) makes
// the truck twitch a little and fails; otherwise the stock goes down by one before the truck's
// gainOneBox sees it, and comes back when there was no taker. A warehouse that empties and is set to
// delete itself is destroyed. (Zero Hour's text: the same function.)
Bool SupplyWarehouseDockUpdate::action(Object *docker, Object *drone)
{
	if (m_boxesStored == 0)
		return FALSE;

	Real closeEnough = docker->getMajorRadius() * 2;
	Real curDistSqr = docker->rva00263763(m_object);
	if (curDistSqr > closeEnough * closeEnough)
	{
		Coord3D newPos;
		newPos.x = docker->getPosition()->x;
		newPos.y = docker->getPosition()->y;
		newPos.z = docker->getPosition()->z;
		newPos.x += GetGameLogicRandomValue(-4, 4, const_cast<char *>(SUPPLY_WAREHOUSE_FILE), 0x57);
		newPos.y += GetGameLogicRandomValue(-4, 4, const_cast<char *>(SUPPLY_WAREHOUSE_FILE), 0x58);
		docker->setPosition(&newPos);
		return FALSE;
	}

	--m_boxesStored;

	SupplyTruckAIInterface *ai = docker->getAIUpdateInterface()->getSupplyTruckAIInterface();
	if (ai && ai->gainOneBox(m_boxesStored))
	{
		if (m_boxesStored == 0 && static_cast<const SupplyWarehouseDockUpdateModuleData *>(getModuleData())->DeleteWhenEmpty)
		{
			TheGameLogic->destroyObject(m_object);
			return FALSE;
		}
		else
		{
			Drawable *draw = m_object->getDrawable();
			if (draw)
				draw->updateDrawableSupplyStatus(static_cast<const SupplyWarehouseDockUpdateModuleData *>(getModuleData())->StartingBoxes, m_boxesStored);
		}
		return TRUE;
	}
	else
		++m_boxesStored;

	return FALSE;
}

// FUNCTION: BFME2 0x004A7F78 size=77 name=?rva004A7F78@SupplyWarehouseDockUpdate@@QAEXH@Z evidence=?:placeholder tier=A
// A script sets the warehouse's cash value: the boxes needed to hold it, rounded up.
void SupplyWarehouseDockUpdate::setCashValue(Int cashValue)
{
	m_boxesStored = (Int)SupplyWarehouseCRT::ceil(cashValue / (Real)TheWritableGlobalData->m_valuePerSupplyBox);
	Drawable *draw = m_object->getDrawable();
	if (draw)
		draw->updateDrawableSupplyStatus(static_cast<const SupplyWarehouseDockUpdateModuleData *>(getModuleData())->StartingBoxes, m_boxesStored);
}

// FUNCTION: BFME2 0x004A7FC5 size=43 name=?loadPostProcess@SupplyWarehouseDockUpdate@@UAEXXZ evidence=N:ledger tier=A
void SupplyWarehouseDockUpdate::loadPostProcess()
{
	DockUpdate::loadPostProcess();
	const SupplyWarehouseDockUpdateModuleData *modData = static_cast<const SupplyWarehouseDockUpdateModuleData *>(getModuleData());
	Object *us = m_object;
	Drawable *draw = us->getDrawable();
	if (draw)
		draw->updateDrawableSupplyStatus(modData->StartingBoxes, m_boxesStored);
}

// FUNCTION: BFME2 0x004A800D size=127 name=?setDockCrippled@SupplyWarehouseDockUpdate@@UAEX_N@Z evidence=N:ledger tier=B hypothesis:cohesion
// Crippling the warehouse kills a truck that is inside it, or sends one that is still approaching back to
// wanting again, before the base class's own handling.
void SupplyWarehouseDockUpdate::setDockCrippled(Bool setting)
{
	if (setting)
	{
		if (m_activeDocker != INVALID_ID)
		{
			Object *victim = TheGameLogic->findObjectByID(m_activeDocker);
			if (victim)
			{
				if (m_dockerInside)
				{
					if (!victim->isUsingAirborneLocomotor())
						victim->kill(DAMAGE_UNRESISTABLE, DEATH_NORMAL);
				}
				else
				{
					SupplyTruckAIInterface *supplyTruckAI = victim->getAI()->getSupplyTruckAIInterface();
					if (supplyTruckAI)
					{
						victim->getAI()->aiIdle(CMD_FROM_AI);
						supplyTruckAI->setForceWantingState(TRUE);
					}
				}
			}
		}
	}

	DockUpdate::setDockCrippled(setting);
}
